-- =====================================================================
-- V1 - Base schema: regions, users, areas (with their polygon vertices)
--      and friend invitations.
--
-- Identifiers
--   id    BIGINT, internal primary key, used by the foreign keys.
--         Never sent through the API. Filled from a sequence per table;
--         the sequences increment by 50 to match Hibernate's pooled
--         allocation (@SequenceGenerator allocationSize = 50).
--   uuid  UUID, public identifier, the only id the API exposes.
--         Generated by Hibernate as UUIDv7 (time ordered). The column
--         default (random v4) is only a fallback for plain SQL inserts.
-- Child rows that are never addressed on their own (area_vertex) have
-- no uuid. Regions use their canton code as key.
-- =====================================================================


-- ---------------------------------------------------------------------
-- Regions: the 26 Swiss cantons, used like an enum.
-- code: the official two-letter canton abbreviation (BE, LU, ...),
-- also used as the value in the frontend (Area.region).
-- ---------------------------------------------------------------------
CREATE TABLE region
(
    code    VARCHAR(2)  NOT NULL,
    name_de VARCHAR(50) NOT NULL,
    name_fr VARCHAR(50) NOT NULL,
    name_it VARCHAR(50) NOT NULL,
    name_en VARCHAR(50) NOT NULL,

    CONSTRAINT pk_region PRIMARY KEY (code),
    CONSTRAINT ck_region_code CHECK (code ~ '^[A-Z]{2}$')
);

